  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\nmodel User {\n  id                 String   @id @default(uuid())\n  username           String   @unique\n  password           String\n  role               String   @default(\"USER\") // ADMIN or USER\n  isTwoFactorEnabled Boolean  @default(false)\n  twoFactorSecret    String?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  letters Letter[]\n}\n\nmodel Letter {\n  id            String   @id @default(uuid())\n  bankName      String   @default(\"Amlak Finance PJSC\")\n  accountNumber String\n  issueDate     DateTime\n  expiryDate    DateTime\n  pdfPath       String?\n  qrCodeData    String?\n  status        String   @default(\"ACTIVE\") // ACTIVE, EXPIRED, REVOKED\n  issuedById    String\n  issuedBy      User     @relation(fields: [issuedById], references: [id])\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\n// ==========================================\n// AMLAK P2P PROCUREMENT & APPROVAL HUB MODELS\n// ==========================================\n\nmodel Rfp {\n  id               String    @id @default(uuid())\n  rfpNumber        String    @unique\n  title            String\n  department       String    @default(\"General Operations\")\n  category         String    @default(\"IT & Infrastructure\")\n  budget           Float     @default(0.0)\n  currency         String    @default(\"AED\")\n  description      String\n  status           String    @default(\"DRAFT\") // DRAFT, PUBLISHED, EVALUATING, APPROVED, AWARDED, REJECTED\n  technicalWeight  Float     @default(60.0)\n  commercialWeight Float     @default(40.0)\n  deadline         DateTime?\n  createdById      String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  proposals      VendorProposal[]\n  approvalTasks  ApprovalTask[]\n  purchaseOrders PurchaseOrder[]\n}\n\nmodel VendorProposal {\n  id              String   @id @default(uuid())\n  rfpId           String\n  rfp             Rfp      @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n  vendorName      String\n  commercialBid   Float\n  technicalScore  Float    @default(0.0) // 0 - 100\n  commercialScore Float    @default(0.0) // 0 - 100\n  totalScore      Float    @default(0.0) // Formula: (Tech * 0.6) + (Comm * 0.4)\n  proposalDetails String?\n  isAwarded       Boolean  @default(false)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel ApprovalTask {\n  id           String         @id @default(uuid())\n  entityType   String // \"RFP\", \"PO\", \"INVOICE\"\n  entityId     String\n  rfpId        String?\n  rfp          Rfp?           @relation(fields: [rfpId], references: [id], onDelete: SetNull)\n  poId         String?\n  po           PurchaseOrder? @relation(fields: [poId], references: [id], onDelete: SetNull)\n  invoiceId    String?\n  invoice      Invoice?       @relation(fields: [invoiceId], references: [id], onDelete: SetNull)\n  level        String         @default(\"L1_DEPT_HEAD\") // L1_DEPT_HEAD, L2_FINANCE_DIRECTOR, L3_CEO_BOARD\n  title        String\n  description  String?\n  amount       Float?\n  status       String         @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  approverRole String         @default(\"MANAGER\")\n  decidedBy    String?\n  comments     String?\n  decidedAt    DateTime?\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n}\n\nmodel PurchaseOrder {\n  id            String   @id @default(uuid())\n  poNumber      String   @unique // e.g. \"AMLAK-PO-2026-8941\" (Oracle EBS simulation)\n  rfpId         String?\n  rfp           Rfp?     @relation(fields: [rfpId], references: [id], onDelete: SetNull)\n  vendorName    String\n  description   String\n  totalAmount   Float\n  currency      String   @default(\"AED\")\n  status        String   @default(\"ISSUED\") // PENDING_APPROVAL, ISSUED, RECEIVED, BILLED, CLOSED, CANCELLED\n  lineItemsJson String?\n  ebsSyncStatus String   @default(\"SYNCED\") // SYNCED, PENDING_SYNC, FAILED\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  approvalTasks ApprovalTask[]\n  goodsReceipts GoodsReceipt[]\n  invoices      Invoice[]\n}\n\nmodel GoodsReceipt {\n  id                 String        @id @default(uuid())\n  grnNumber          String        @unique // e.g. \"GRN-2026-1042\"\n  poId               String\n  po                 PurchaseOrder @relation(fields: [poId], references: [id], onDelete: Cascade)\n  receivedQuantity   Int           @default(1)\n  deliveryNoteNumber String?\n  receivedDate       DateTime      @default(now())\n  inspectedBy        String        @default(\"Warehouse Admin\")\n  condition          String        @default(\"PASSED\") // PASSED, DAMAGED, DEFECTIVE\n  notes              String?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  invoices Invoice[]\n}\n\nmodel Invoice {\n  id            String        @id @default(uuid())\n  invoiceNumber String        @unique // e.g. \"INV-99214\"\n  poId          String\n  po            PurchaseOrder @relation(fields: [poId], references: [id], onDelete: Cascade)\n  grnId         String?\n  grn           GoodsReceipt? @relation(fields: [grnId], references: [id], onDelete: SetNull)\n  vendorName    String\n  billedAmount  Float\n  poAmount      Float\n  status        String        @default(\"PENDING_MATCH\") // PENDING_MATCH, MATCHED, DISCREPANCY, APPROVED, PAID\n  matchResult   String? // JSON summary of 3-Way match\n  paymentDate   DateTime?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  approvalTasks ApprovalTask[]\n}\n",
